/* COSC 407/507 Lab 4, core A -- k1, the program you parallelise.
 *
 * *** DO NOT EDIT THIS FILE. *** It is hashed. Work in fix/k1.c, which
 * starts as a copy of it.
 *
 * What it does: makes n random numbers x in [0, 1), then adds up
 *
 *         sqrt(x) * sin(10 x)
 *
 * over all of them. Two phases, timed separately:
 *
 *   setup   lab4_fill_unit() makes the numbers. Each one is computed from the
 *           one before it, so this phase is serial and stays serial.
 *   kernel  the loop in kernel() below. Every iteration is independent of the
 *           others except for the running sum. This is what you parallelise.
 *
 *   bin/k1 [threads] [n]          defaults: 4 threads, n = 16777216 (2^24)
 */
#include "lab4.h"

double ref_k1(const double *x, long n);   /* src/ref.c: the same sum, serial */

static double kernel(const double *x, long n)
{
    double sum = 0.0;
    for (long i = 0; i < n; i++) {
        sum += sqrt(x[i]) * sin(10.0 * x[i]);
    }
    return sum;
}

int main(int argc, char **argv)
{
    lab4_args_t a = lab4_args(argc, argv, 1L << 24);
    double *x = lab4_alloc((size_t)a.n * sizeof *x);

    double t0 = lab4_now();
    lab4_fill_unit(x, a.n, 407);              /* setup: serial */
    double t1 = lab4_now();
    double r = kernel(x, a.n);                /* kernel: parallelise this */
    double t2 = lab4_now();

    int ok = lab4_close(r, ref_k1(x, a.n));   /* checked after the clock stops */
    lab4_report("k1", a, t1 - t0, t2 - t1, t2 - t0, r, ok);
    free(x);
    return ok ? 0 : 1;
}
